CREATE FUNCTION wl.canonical_dimension_hash(input jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
    SELECT encode(
        digest(
            (
                SELECT string_agg(key || '=' || value, '|')
                FROM (
                    SELECT key, value
                    FROM jsonb_each_text(input)
                    ORDER BY key
                ) ordered
            ),
            'sha256'
        ),
        'hex'
    );
$$;

